from __future__ import annotations

import inspect

__all__ = ["clean_f_str"]


def clean_f_str(text: str) -> str:
    """
    Strip source indentation and the blank first/last lines from a triple-quoted (f-)string.

    Caveat: an inserted value that spans multiple lines lowers the common indent, so the
    indentation is left in. Keep such values on one line or indent them to match.

    ```python
    clean_f_str(
        f'''
        Hello {name}
        Rules: ...
        '''
    )
    ```
    """
    return inspect.cleandoc(text)
